// Generated by OrchestKit Claude Plugin
// Created: 2026-08-09

/**
 * Handoff injection claim + shared handoff-store lookup (#3329)
 *
 * ork ships TWO across-time handoff loops that both open their injected text
 * with the marker `[Previous Session Handoff]`:
 *
 *   global YAML  SessionEnd  lifecycle/session-handoff-generator
 *                SessionStart lifecycle/session-handoff-injector
 *                ~/.claude/analytics/handoffs/<sha256(projectDir)>/latest.yaml
 *
 *   repo-local   Stop         stop/handoff-writer
 *                UserPromptSubmit prompt/handoff-injector (runOnce)
 *                <projectDir>/.claude/HANDOFF.md
 *
 * Nothing coordinated them, so a session with both stores populated got the
 * marker twice. #3329 defers deleting the global pair until the repo-local
 * injector has been taught to serve the global store and that fallback has
 * been measured firing. This module is what makes that sequencing safe:
 *
 *   claimHandoffInjection()  at most ONE injection per session, enforced by an
 *                            exclusive-create flag file (no TOCTOU window)
 *   readGlobalHandoff()      one implementation of the global-store read, so
 *                            the fallback and the SessionStart hook cannot
 *                            drift on staleness or size limits
 *   hasFreshLocalHandoff()   lets the SessionStart hook yield to the
 *                            repo-local loop, which #3329 designates as the
 *                            surviving one
 *
 * SCOPE NOTE — hashProject(). `lib/analytics.ts` hashes the raw projectDir with
 * no git-toplevel normalization, so a linked worktree and its parent checkout
 * land in different global buckets. That is real, and it is why a worktree
 * session usually finds no global handoff. It does NOT affect the claim: both
 * hooks receive the same session_id and the same project_dir within one
 * session, so they always compute the same claim path regardless of how
 * hashProject buckets the store. Discovery and dedup are separate concerns and
 * only discovery is affected; normalizing the hash would re-bucket every
 * existing analytics path and is deliberately out of scope here.
 */

import { existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { getHomeDir, getSessionStorageDir, joinPath } from './paths.js';
import { hashProject } from './analytics.js';

/** A handoff older than this is not worth replaying. */
export const HANDOFF_MAX_AGE_MS = 24 * 60 * 60 * 1000;

/** Guard against an oversized global handoff eating the context window. */
export const HANDOFF_MAX_FILE_SIZE = 4096;

/** Shared opening marker. Both loops emit it; only one may per session. */
export const HANDOFF_MARKER = '[Previous Session Handoff]';

/** The one claim key. Both loops compete for it. */
const CLAIM_NAME = 'handoff-injected.done';

/**
 * Session flag directory. Mirrors prompt/unified-dispatcher's once-flag tree
 * so the claim lives beside the runOnce flags rather than in a second scheme.
 */
function sessionFlagDir(sessionId: string, projectDir: string): string {
  const base = process.env.CLAUDE_PLUGIN_DATA
    ? join(getSessionStorageDir(), sessionId)
    : join(projectDir, '.claude', 'memory', 'sessions', sessionId);
  return join(base, 'once-flags');
}

/**
 * Claim the single per-session handoff injection.
 *
 * Returns true exactly once per (session, project): the caller that gets true
 * owns the injection, every later caller gets false and must stay silent.
 *
 * Uses an exclusive-create write (`flag: 'wx'`) rather than existsSync-then-
 * write, so two hooks racing in the same session cannot both win.
 *
 * Fails OPEN (returns true) when there is no session id or the flag tree is
 * unwritable: losing continuity is a worse outcome than a rare duplicate, and
 * the duplicate was the pre-#3329 status quo anyway.
 */
export function claimHandoffInjection(
  sessionId: string | undefined,
  projectDir: string,
  claimant: string,
): boolean {
  if (!sessionId) return true;

  const dir = sessionFlagDir(sessionId, projectDir);
  const path = join(dir, CLAIM_NAME);

  try {
    mkdirSync(dir, { recursive: true });
    writeFileSync(path, `${new Date().toISOString()} ${claimant}\n`, {
      encoding: 'utf8',
      flag: 'wx',
    });
    return true;
  } catch (err) {
    // EEXIST is the designed outcome: someone else already injected.
    if ((err as NodeJS.ErrnoException)?.code === 'EEXIST') return false;
    return true;
  }
}

/** Absolute path of the global handoff store for a project. */
export function globalHandoffPath(projectDir: string): string {
  return joinPath(
    getHomeDir(),
    '.claude',
    'analytics',
    'handoffs',
    hashProject(projectDir),
    'latest.yaml',
  );
}

/**
 * Read the global handoff store, applying the age and size guards.
 * Returns the trimmed body, or null with a machine-readable reason.
 */
export function readGlobalHandoff(
  projectDir: string,
): { body: string } | { body: null; reason: string } {
  const path = globalHandoffPath(projectDir);
  if (!existsSync(path)) return { body: null, reason: 'absent' };

  let stat: ReturnType<typeof statSync>;
  try {
    stat = statSync(path);
  } catch {
    return { body: null, reason: 'unstattable' };
  }

  if (Date.now() - stat.mtimeMs > HANDOFF_MAX_AGE_MS) {
    return { body: null, reason: 'stale' };
  }
  if (stat.size > HANDOFF_MAX_FILE_SIZE) {
    return { body: null, reason: `oversized (${stat.size} bytes)` };
  }

  let body: string;
  try {
    body = readFileSync(path, 'utf-8').trim();
  } catch {
    return { body: null, reason: 'unreadable' };
  }
  return body ? { body } : { body: null, reason: 'empty' };
}

/** Absolute path of the repo-local handoff store. */
export function localHandoffPath(projectDir: string): string {
  return join(projectDir, '.claude', 'HANDOFF.md');
}

/**
 * True when a repo-local handoff exists and is inside the age window.
 *
 * The SessionStart hook uses this to YIELD: #3329 designates the repo-local
 * loop as the surviving one, and SessionStart fires first, so without this
 * check the global store would always win the claim and the repo-local
 * handoff would never be seen again.
 */
export function hasFreshLocalHandoff(projectDir: string): boolean {
  const path = localHandoffPath(projectDir);
  if (!existsSync(path)) return false;
  try {
    return Date.now() - statSync(path).mtimeMs <= HANDOFF_MAX_AGE_MS;
  } catch {
    return false;
  }
}
